<div class="page-head"><div><h3>Materials master</h3><p>One row per material, matching the RD-10 specification.</p></div><?php if(is_admin()): ?><button class="primary" onclick="document.getElementById('addMaterial').showModal()">＋ Add material</button><?php endif; ?></div><section class="panel"><form class="toolbar"><input name="q" placeholder="Search code, description or vendor"><button class="secondary">Search</button></form><div class="table-wrap"><table><thead><tr><th>Code</th><th>Description</th><th>Type</th><th>Vendor</th><th>Unit</th><th>Capacity</th><th>Plan</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= esc($r['code']) ?></b></td><td><?= esc($r['description']) ?></td><td><?= esc($r['type']) ?></td><td><?= esc($r['vendor_name']??'') ?></td><td><?= esc($r['unit']) ?></td><td><?= number_format($r['monthly_capacity'],3) ?></td><td><?= number_format($r['production_plan'],3) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php if(is_admin()): ?><dialog id="addMaterial"><form method="post" action="<?= base_url('materials/create') ?>"><h3>Add material</h3><?= csrf_field() ?><div class="form-grid"><?php foreach([['code','Code'],['description','Description'],['vendor_name','Vendor'],['unit','Unit'],['monthly_capacity','Monthly capacity'],['production_plan','Production plan']] as $x): ?><label><?= $x[1] ?><input name="<?= $x[0] ?>" required></label><?php endforeach; ?></div><button class="primary">Save</button><button type="button" class="secondary" onclick="this.closest('dialog').close()">Cancel</button></form></dialog><?php endif; ?>